/**
 * Forced Move (animated) — push/pull relative to caster / template / clicked point
 * - uses MidiQOL.moveToken(..., true) to play animation
 * - snaps final center per token parity (odd->cell center, even->grid intersection)
 * - steps back by grid until a free cell is found (or fails)
 * - supports using the most recently placed measured template as source
 */

(async () => {
  // ---------- 配置 / helper ----------
  const gs = canvas.grid.size;
  const feetPerSquare = canvas.scene.grid?.distance ?? 5;
  const S = CONST.GRID_SNAPPING_MODES;

  function pxFromFeet(feet) { return (feet / feetPerSquare) * gs; }
  function getCanvasTokenCenter(tok) { return { x: (tok.center?.x ?? (tok.x + tok.w/2)), y: (tok.center?.y ?? (tok.y + tok.h/2)) }; }
  function getTokenGridSize(tok) { return { w: Math.max(1, Math.floor(Number(tok.document?.width ?? tok.document?._source?.width ?? tok._source?.width ?? 1))), h: Math.max(1, Math.floor(Number(tok.document?.height ?? tok.document?._source?.height ?? tok._source?.height ?? tok.document?.width ?? 1))) }; }

  // snap stage point to cell center (BASE grid)
  function snapCellCenter(stagePoint) {
    try { return canvas.grid.getSnappedPoint({ x: stagePoint.x, y: stagePoint.y }, { mode: S.CENTER, resolution: 1 }); }
    catch (e) { return { x: Math.round(stagePoint.x/gs)*gs, y: Math.round(stagePoint.y/gs)*gs }; }
  }
  // snap to grid intersection (integer multiples of gs)
  function snapIntersection(stagePoint) {
    return { x: Math.round(stagePoint.x/gs)*gs, y: Math.round(stagePoint.y/gs)*gs };
  }

  // given a desired center point and token parity, produce the "snapped center" and corresponding top-left pixel
  function computeSnappedForTokenCenter(desiredCenter, tokenGridW, tokenGridH) {
    // for each axis choose cell-center or intersection depending on parity
    const snappedX = (tokenGridW % 2 === 1) ? snapCellCenter(desiredCenter).x : snapIntersection(desiredCenter).x;
    const snappedY = (tokenGridH % 2 === 1) ? snapCellCenter(desiredCenter).y : snapIntersection(desiredCenter).y;
    const col = Math.floor(snappedX / gs), row = Math.floor(snappedY / gs);
    const topLeftCol = col - Math.floor(tokenGridW / 2);
    const topLeftRow = row - Math.floor(tokenGridH / 2);
    const topLeftX = Math.round(topLeftCol * gs), topLeftY = Math.round(topLeftRow * gs);
    const centerX = Math.round((topLeftCol + tokenGridW/2) * gs), centerY = Math.round((topLeftRow + tokenGridH/2) * gs);
    return { center: { x: centerX, y: centerY }, topLeft: { x: topLeftX, y: topLeftY }, grid: { col: topLeftCol, row: topLeftRow } };
  }

  // occupancy check of rectangle (ignore token id)
  function rectOccupied(px, py, wpx, hpx, ignoreId=null) {
    const rectA = new PIXI.Rectangle(px, py, wpx, hpx);
    return canvas.tokens.placeables.some(t => {
      if (t.id === ignoreId) return false;
      const rectB = new PIXI.Rectangle(t.x, t.y, t.w, t.h);
      return rectA.right > rectB.left && rectA.left < rectB.right && rectA.bottom > rectB.top && rectA.top < rectB.bottom;
    });
  }

  // prompt map click
  async function promptClick(timeout=20000, hint="请在地图上点击选择点") {
    ui.notifications.info(hint);
    return new Promise(resolve => {
      const handler = ev => {
        try { canvas.app.stage.off("pointerdown", handler); } catch(e){}
        let p = null;
        try { p = ev.data.getLocalPosition(canvas.app.stage); } catch(e) { p = null; }
        resolve(p);
      };
      canvas.app.stage.on("pointerdown", handler);
      setTimeout(() => { try { canvas.app.stage.off("pointerdown", handler); } catch(e){}; resolve(null); }, timeout);
    });
  }

  // attempt move: given token, desiredCenterPx (raw), try to find a snapped free spot by stepping back by gs increments along vector until found or zero
  async function findAndMoveToken(tok, desiredCenterPx, requestedPixels, preferMoveFromPoint=false, sourcePoint=null, animate=true) {
    const { w: tgW, h: tgH } = getTokenGridSize(tok);
    // build list of candidate distances (from requested down to 0 step gs)
    const steps = [];
    for (let s = requestedPixels; s >= 0; s -= gs) steps.push(s);
    if (steps[steps.length-1] !== 0) steps.push(0);

    // compute original center
    const cur = getCanvasTokenCenter(tok);
    // unit vector from cur -> desired (if desiredCenterPx provided) else use vector from source->token for move_from_point case
    let vecX = desiredCenterPx.x - cur.x;
    let vecY = desiredCenterPx.y - cur.y;
    let norm = Math.hypot(vecX, vecY);
    if (norm < 1e-6) { vecX = 1; vecY = 0; norm = 1; }
    const ux = vecX / norm, uy = vecY / norm;

    for (const step of steps) {
      // candidate raw center = cur + unit * step
      const candRaw = { x: Math.round(cur.x + ux * step), y: Math.round(cur.y + uy * step) };
      const snap = computeSnappedForTokenCenter(candRaw, tgW, tgH);
      // occupancy check
      const occ = rectOccupied(snap.topLeft.x, snap.topLeft.y, tgW*gs, tgH*gs, tok.id);
      if (!occ) {
        // perform move
        try {
          // If preferMoveFromPoint and MidiQOL.moveTokenFromPoint exists and we have a sourcePoint, we could call it.
          // BUT to guarantee final snapped alignment, we still call MidiQOL.moveToken to the snapped center (with animation).
          if (typeof MidiQOL?.moveToken === "function") {
            await MidiQOL.moveToken(tok, { x: snap.center.x, y: snap.center.y }, Boolean(animate));
            return { moved: true, center: snap.center, attemptedPixels: step };
          } else {
            return { moved: false, reason: "no-midi-qol" };
          }
        } catch (e) {
          console.error("ForcedMove: MidiQOL.moveToken failed", e);
          return { moved: false, reason: "move-failed", error: e };
        }
      }
      // else occupied => try next smaller step
    }
    return { moved: false, reason: "blocked" };
  }

  // ---------- UI: 参数对话 ----------
  const dlg = await new Promise(resolve => {
    new Dialog({
      title: "强制位移 (push/pull)",
      content: `
      <form>
        <div class="form-group">
          <label>参考点 (mode)</label>
          <select id="fm-mode"><option value="caster">施法者 (控制的 Token)</option><option value="template">最近放置的测量模板</option><option value="point">手动点击</option></select>
        </div>
        <div class="form-group">
          <label>方向</label>
          <select id="fm-dir"><option value="away">远离 (push)</option><option value="toward">靠近 (pull)</option></select>
        </div>
        <div class="form-group">
          <label>距离（英尺）</label>
          <input id="fm-dist" type="number" value="15" step="1" />
        </div>
        <div class="form-group">
          <label>目标来源</label>
          <select id="fm-targets"><option value="targets">使用 game.user.targets</option><option value="controlled">使用控制的 tokens (除 caster)</option></select>
        </div>
        <div class="form-group">
          <label>动画</label>
          <select id="fm-anim"><option value="true">播放动画</option><option value="false">不播放动画</option></select>
        </div>
        <div class="form-group">
          <label>优先使用 MidiQOL.moveTokenFromPoint (若可用)</label>
          <select id="fm-pref"><option value="false">否 (默认，用 moveToken 保证 snap)</option><option value="true">是 (若可用)</option></select>
        </div>
      </form>
      `,
      buttons: {
        ok: { label: "确定", callback: (html) => {
          resolve({
            mode: html.find("#fm-mode").val(),
            dir: html.find("#fm-dir").val(),
            dist: Number(html.find("#fm-dist").val()) || 0,
            targetMode: html.find("#fm-targets").val(),
            animate: html.find("#fm-anim").val() === "true",
            preferMoveFromPoint: html.find("#fm-pref").val() === "true"
          });
        }},
        cancel: { label: "取消", callback: () => resolve(null) }
      },
      default: "ok"
    }).render(true);
  });

  if (!dlg) return ui.notifications.info("已取消强制位移");

  // ---------- resolve source point ----------
  let sourcePoint = null;
  let casterToken = canvas.tokens.controlled[0] ?? token ?? null;
  if (dlg.mode === "caster") {
    if (!casterToken) { ui.notifications.warn("请先控制（选中）施法者 Token"); return; }
    sourcePoint = getCanvasTokenCenter(casterToken);
  } else if (dlg.mode === "template") {
    // pick most recently placed measured template (if any). If none, fallback to prompting click
    const templates = canvas.templates.placeables ?? [];
    if (!templates || templates.length === 0) {
      ui.notifications.info("场景中未检测到测量模板，将要求手动点击选择点");
      const p = await promptClick(20000, "请点击地图以选择参考点（模板缺失）");
      if (!p) { ui.notifications.warn("取消"); return; }
      sourcePoint = snapCellCenter(p);
    } else {
      // use last placed
      const last = templates[templates.length - 1];
      // try to read center: some template objects have .center; fallback compute from x,y and shape/radius
      let tCenter = null;
      try { tCenter = last.center ?? { x: last.x ?? last.document?.x ?? 0, y: last.y ?? last.document?.y ?? 0 }; } catch(e) { tCenter = { x: last.x ?? 0, y: last.y ?? 0 }; }
      sourcePoint = { x: Math.round(tCenter.x), y: Math.round(tCenter.y) };
      ui.notifications.info(`使用最近的测量模板作为参考点（id=${last.id ?? last.document?.id ?? "unknown"}）`);
    }
  } else {
    const p = await promptClick(20000, "请在地图上点击以选择参考点（圆心）");
    if (!p) { ui.notifications.warn("未选择点，取消"); return; }
    sourcePoint = snapCellCenter(p);
  }

  // ---------- resolve targets ----------
  let targets = [];
  if (dlg.targetMode === "targets") targets = Array.from(game.user.targets ?? []);
  else targets = canvas.tokens.controlled.filter(t => t.id !== (casterToken?.id ?? null));
  if (!targets || targets.length === 0) { ui.notifications.warn("未检测到目标 (targets 或 控制的 token)"); return; }

  // ---------- per-target movement ----------
  const distancePixels = pxFromFeet(dlg.dist);
  const dirSign = (dlg.dir === "away") ? 1 : -1;

  const results = [];
  for (const tk of targets) {
    // compute vector from source -> token (for away), or token -> source (for toward we invert)
    const tkCenter = getCanvasTokenCenter(tk);
    let vx = tkCenter.x - sourcePoint.x;
    let vy = tkCenter.y - sourcePoint.y;
    let distFromSourcePx = Math.hypot(vx, vy);
    if (distFromSourcePx < 1e-6) { vx = 1; vy = 0; distFromSourcePx = 1; } // avoid zero vector

    // desired move along normalized vector
    const ux = (vx / distFromSourcePx) * dirSign;
    const uy = (vy / distFromSourcePx) * dirSign;

    // if toward and requested distance > distanceToSource, cap so we don't cross source
    let requestedPixels = distancePixels;
    if (dlg.dir === "toward") requestedPixels = Math.min(distancePixels, distFromSourcePx - (gs * 0.01)); // small epsilon

    if (requestedPixels <= 0) {
      results.push({ token: tk, moved: false, reason: "zero-effective-distance" });
      continue;
    }

    // desired raw center to attempt = current center + unit * requestedPixels
    const desiredRaw = { x: Math.round(tkCenter.x + ux * requestedPixels), y: Math.round(tkCenter.y + uy * requestedPixels) };

    // use findAndMoveToken which will attempt stepping back by gs to find free snapped spot and call MidiQOL.moveToken(..., animate)
    const r = await findAndMoveToken(tk, desiredRaw, requestedPixels, dlg.preferMoveFromPoint, sourcePoint, dlg.animate);
    results.push({ token: tk, ...r, requestedFeet: dlg.dist });
  }

  // ---------- report ----------
  for (const r of results) {
    if (r.moved) ChatMessage.create({ content: `${r.token.name} 被移动 ${Math.round((r.attemptedPixels / gs) * feetPerSquare)} 英尺 (${dlg.dir})` });
    else ChatMessage.create({ content: `${r.token.name} 未能移动：${r.reason ?? "unknown"}` });
  }

  console.log("ForcedMove (animated) finished", results);
})();
